self.KB_CONTENT["card:753628"]={"id":"card:753628","ty":"card","sourceId":"753628","title":"『客戶訂單建立作業』中的『簽核狀態 (TC048)』為何？","ver":"iGP","topic":"客戶","keywords":["客戶","訂單","狀態","電子"],"y":"other","answer":"* 簽核狀態碼區分為0.待處理、1.簽核中、2.退件、3.已核准、4.取消確認中、5.作廢中、6.取消作廢中及N.不執行電子簽核。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
