self.KB_CONTENT["card:779448"]={"id":"card:779448","ty":"card","sourceId":"779448","title":"『出貨通知單建立作業(IDL)』的作業目的為何？","ver":"GP4以上","topic":"明細","keywords":["明細","客戶","出貨","包裝"],"y":"explain","answer":"可通知客戶即將出貨的貨品明細，及通知外包開始包裝，包裝明細可再於packing list建立作業輸入。輸入完成之出貨通知單可列印INVOICE。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
