self.KB_CONTENT["card:779013"]={"id":"card:779013","ty":"card","sourceId":"779013","title":"『出貨通知單建立作業(IDL)』中的『毛重 (TB034)』為何？","ver":"GP4以上","topic":"出貨","keywords":["出貨","大於","等於"],"y":"other","answer":"* 此欄位必須大於等於零。* 作數量之取位至小數點下三位。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
