self.KB_CONTENT["card:891102"]={"id":"card:891102","ty":"card","sourceId":"891102","title":"如何啟動庫別儲位管理?","ver":"GP40.iGP 以上","topic":"庫別","keywords":["庫別","儲位","啟動"],"y":"howto","answer":"請至基本資料管理系統->建立作業->『庫別資料建立作業-CMSI03』選擇庫別維護儲位，執行『庫別儲位管理啟動/取消作業-CMSB07』啟動該庫別的儲位管理，選好庫別後點選向下箭頭，維護【主要儲位】點選確認即可。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
