self.KB_CONTENT["field:792418"]={"id":"field:792418","ty":"field","sourceId":"792418","title":"匯率","ver":"GP4以上","topic":"","keywords":[],"job":"借支申請單建立作業","code":"TE007","answer":"* 此欄位必須大於零。* 可點選(icon)或[F2]銀行賣出匯率查詢。* 預設本幣金額=原幣金額×匯率，須作本國幣別取位。","file":"fields.jsonl"};
