self.KB_CONTENT["field:758720"]={"id":"field:758720","ty":"field","sourceId":"758720","title":"簽核狀態","ver":"iGP","topic":"","keywords":[],"job":"進貨單建立作業","code":"TG042","answer":"* 此欄位僅作顯示。簽核狀態類型區分為0.待處理、1.簽核中、2.退件、3.已核准、4.取消確認中、5.作廢中、6.取消作廢中及N.不執行電子簽核。","file":"fields.jsonl"};
